USE [master];SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @D varchar(7)='$(DemoId)',@R varchar(20)='$(RunToken)',@T sysname=N'$(TargetDatabase)',@P nvarchar(max),@C nvarchar(max),@ED nvarchar(max),@ER nvarchar(max),@S nvarchar(max);IF @D<>'CON-009' OR @T<>N'SQLPERF_LAB_CON009_'+@R THROW 51000,'FAIL_CONTRACT: CON-009-Cleanupziel ist ungueltig.',1;IF DB_ID(@T) IS NULL BEGIN PRINT 'SQLPERF_SUMMARY|PASS|OK';RETURN;END;SET @S=N'SELECT @P=MAX(CASE WHEN name=N''SQLPERF.Project'' THEN CONVERT(nvarchar(max), value) END),@C=MAX(CASE WHEN name=N''SQLPERF.ContractVersion'' THEN CONVERT(nvarchar(max), value) END),@D=MAX(CASE WHEN name=N''SQLPERF.DemoId'' THEN CONVERT(nvarchar(max), value) END),@R=MAX(CASE WHEN name=N''SQLPERF.RunToken'' THEN CONVERT(nvarchar(max), value) END) FROM '+QUOTENAME(@T)+N'.sys.extended_properties WHERE class=0;';EXEC sys.sp_executesql @S,N'@P nvarchar(max) OUT,@C nvarchar(max) OUT,@D nvarchar(max) OUT,@R nvarchar(max) OUT',@P OUT,@C OUT,@ED OUT,@ER OUT;IF @P IS NULL OR @P COLLATE Latin1_General_100_BIN2 <> N'SQL_PerformanceSchulung' OR DATALENGTH(@P) <> DATALENGTH(N'SQL_PerformanceSchulung')
   OR @C IS NULL OR @C COLLATE Latin1_General_100_BIN2 <> N'1.0' OR DATALENGTH(@C) <> DATALENGTH(N'1.0')
   OR @ED IS NULL OR @ED COLLATE Latin1_General_100_BIN2 <> CONVERT(nvarchar(max), @D) OR DATALENGTH(@ED) <> DATALENGTH(CONVERT(nvarchar(max), @D))
   OR @ER IS NULL OR @ER COLLATE Latin1_General_100_BIN2 <> CONVERT(nvarchar(max), @R) OR DATALENGTH(@ER) <> DATALENGTH(CONVERT(nvarchar(max), @R)) THROW 51004,'FAIL_CLEANUP: CON-009-Marker stimmen nicht.',1;SET @S=N'ALTER DATABASE '+QUOTENAME(@T)+N' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;DROP DATABASE '+QUOTENAME(@T)+N';';EXEC(@S);PRINT 'SQLPERF_SUMMARY|PASS|OK';
